263		}
264	
265		// Empty object has no version field and must be rejected rather than
266		// treated as a fresh registry.
267		t.Run("empty object", func(t *testing.T) {
268			path := filepath.Join(dir, "obj.json")
269			writeRegistry(t, path, `{}`)
270			if _, _, err := Load(path); err == nil {
