func TestParseImportInputRejects(t *testing.T) {
	cases := map[string]string{
		"empty file":        "",
		"whitespace":        "  \n\t ",
		"empty array":       "[]",
		"object":            `{"batch":"B1"}`,
		"string":            `["B1"]`,
		"number":            `[1,2]`,
